effect.frag.content:
int sourceIndex = 0;
uniform float u_amount;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return imageAt(sourceIndex, uv);
}
void main() {
  float count = 2.0 + floor(u_amount * 10.0);
  vec2 cell = floor(v_uv * count + vec2(u_progress * float(inputCount)));
  sourceIndex = int(cell.x + cell.y * count);
  vec2 uv = fract(v_uv * count + vec2(u_progress * float(inputCount)));
  fragColor = sourceAt(uv);
}
